{"function":"async () => {
// list tabbable elements in order including shadow roots (approximation via sequential focus is better; done via keyboard later)
const res=[];
const walk=(root)=>{ root.querySelectorAll('*').forEach(e=>{ if(e.shadowRoot) walk(e.shadowRoot); if(e.tabIndex>=0 && !e.disabled && e.offsetParent!==null && (e.matches('a[href],button,input,select,textarea,[tabindex]'))) res.push((e.tagName+' '+(e.getAttribute('aria-label')||e.textContent.trim().slice(0,30)||e.type||'')).slice(0,60)); }); };
walk(document);
return {n: res.length, first: res.slice(0,30)};
}"}

